def read_number(n: int) -> str:
    if n == 0:
        return '영'

    # Digit names
    digits = ['', '일', '이', '삼', '사', '오', '육', '칠', '팔', '구']

    # Place values within a group of 4
    places = ['', '십', '백', '천']

    def read_group(num):
        """Read a group of 4 digits (0-9999)"""
        if num == 0:
            return ''

        result = ''
        for i in range(4):
            digit = (num // (10 ** i)) % 10
            if digit != 0:
                # Add digit name, then place value (except for ones place)
                if i == 0:  # ones place
                    result = digits[digit] + result
                else:
                    result = digits[digit] + places[i] + result

        return result

    # Split into groups: ones (0-9999), 만 (10000-99999999), 억 (100000000+)
    ones = n % 10000
    mans = (n // 10000) % 10000
    eoks = (n // 100000000) % 10000

    result = ''

    # Eok group (억)
    if eoks > 0:
        result += read_group(eoks) + '억'

    # Man group (만)
    if mans > 0:
        if mans == 1:
            result += '만'
        else:
            result += read_group(mans) + '만'

    # Ones group
    if ones > 0:
        result += read_group(ones)

    return result
